package com.oms.supplychain.service.wms;
import org.junit.jupiter.api.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.supplychain.service.wms.WmsStore.*;

class ReturnQueryWarehouseTest {
    SharedReturnParcelsTest f;ReturnQueryWarehouse query;
    @BeforeEach void setup(){f=new SharedReturnParcelsTest();f.setup();for(String table:Arrays.asList("wms_refund_parcel_receipt","wms_refund_parcel_document","wms_refund_parcel_member","wms_refund_parcel"))f.f.jdbc.update("DELETE FROM "+table);query=new ReturnQueryWarehouse();query.db=f.f.db;query.routes=mock(WmsTenantRoutes.class);}
    @Test void snapshotsReturnActualCommonWarehouseNumberAndKeepPrivateSourceQuantity(){List<Map<String,Object>> rows=query.snapshots("QM",Arrays.asList(map("owner_kind","EXCHANGE","source_id",1),map("owner_kind","REFUND","source_id",2)));assertEquals(2,rows.size());for(Map<String,Object> r:rows){assertEquals("THKX_TEST",r.get("return_sn"));assertEquals(2,id(r.get("expected_members")));assertTrue(r.get("parcel_key").toString().startsWith("SHARED:"));assertFalse(r.containsKey("input_json"));assertFalse(r.containsKey("lease_token"));}assertEquals(8,rows.stream().mapToLong(r->id(r.get("quantity"))).sum());verifyNoInteractions(f.f.inventory);}
    @Test void collectingParcelHasNoPublishedWarehouseCommand(){f.f.jdbc.update("DELETE FROM wms_shared_return_document");Map<String,Object> r=query.snapshots("QM",Collections.singletonList(map("owner_kind","EXCHANGE","source_id",1))).get(0);assertEquals("",r.get("return_sn"));assertNotNull(r.get("dispatch_after"));verifyNoInteractions(f.f.inventory);}
    @Test void oldAcknowledgementCannotDiscardANewerWarehouseProgressChange(){f.f.jdbc.update("INSERT INTO wms_return_query_dirty(company_code,owner_kind,source_id,work_version) VALUES ('QM','EXCHANGE',1,20) ON DUPLICATE KEY UPDATE work_version=20");query.acknowledge("QM",Collections.singletonList(map("owner_kind","EXCHANGE","source_id",1,"work_version",19)));assertEquals(20,f.f.jdbc.queryForObject("SELECT work_version FROM wms_return_query_dirty WHERE company_code='QM' AND owner_kind='EXCHANGE' AND source_id=1",Long.class));query.acknowledge("QM",Collections.singletonList(map("owner_kind","EXCHANGE","source_id",1,"work_version",20)));assertEquals(0,f.f.jdbc.queryForObject("SELECT COUNT(*) FROM wms_return_query_dirty WHERE company_code='QM' AND owner_kind='EXCHANGE' AND source_id=1",Integer.class));}
    @Test void tenantCannotReadOrAcknowledgeAnotherCompany(){assertTrue(query.snapshots("OTHER",Collections.singletonList(map("owner_kind","EXCHANGE","source_id",1))).isEmpty());f.f.jdbc.update("INSERT INTO wms_return_query_dirty(company_code,owner_kind,source_id,work_version) VALUES ('QM','EXCHANGE',1,20) ON DUPLICATE KEY UPDATE work_version=20");query.acknowledge("OTHER",Collections.singletonList(map("owner_kind","EXCHANGE","source_id",1,"work_version",20)));assertEquals(20,f.f.jdbc.queryForObject("SELECT work_version FROM wms_return_query_dirty WHERE company_code='QM' AND owner_kind='EXCHANGE' AND source_id=1",Long.class));}
    @Test void excessiveOrInvalidSourceBatchIsRejectedBeforeAnyWarehouseWork(){assertThrows(IllegalArgumentException.class,()->query.snapshots("QM",Collections.nCopies(501,map("owner_kind","EXCHANGE","source_id",1))));assertThrows(IllegalArgumentException.class,()->query.snapshots("QM",Collections.singletonList(map("owner_kind","SQL","source_id",1))));verifyNoInteractions(f.f.inventory);}
    @Test void stoppedOriginalRefundWarehouseDocumentRemainsTraceableAfterMembershipMoves(){f.f.jdbc.update("UPDATE wms_refund_return SET shared_member_id=NULL");long parcel=f.f.db.insert("wms_refund_parcel",map("company_code","QM","parcel_sn","RP_OLD_QUERY","carrier_code","SF","waybill","OLD_QUERY_WAYBILL","store_code","V1","connection_id",1,"external_owner","EXT-O","external_warehouse","EXT-W","owner_code","O","real_store_code","W","actor","test","reason","test","evidence","test"));f.f.db.insert("wms_refund_parcel_member",map("company_code","QM","parcel_id",parcel,"plan_id",2,"generation",1,"task_id",f.refundTask,"refund_id",20,"refund_sn","TK_TEST","order_sn","SO_TEST","source_line_id",1,"sku_sn","G","quantity",3,"actor","test","reason","test","evidence","test","active",0));f.f.db.insert("wms_refund_parcel_document",map("company_code","QM","parcel_id",parcel,"return_sn","THK_OLD_QUERY","quantity",3,"payload","[]","cancel_state","CONFIRMED"));Map<String,Object> r=query.snapshots("QM",Collections.singletonList(map("owner_kind","REFUND","source_id",2))).get(0);assertEquals("THK_OLD_QUERY",r.get("return_sn"));assertEquals("CONFIRMED",r.get("cancel_state"));assertEquals(1,id(r.get("expected_members")));verifyNoInteractions(f.f.inventory);}
}
